const bufferProfile = (platform) => norm($env['BUFFER_PROFILE_ID_' + String(platform).toUpperCase()]);
const AI_MODEL = norm($env.AI_MODEL) || 'llama-3.3-70b-versatile';
const aiRequest = (system, user, temperature) => ({
  model: AI_MODEL, temperature: temperature === undefined ? 0.7 : temperature, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
});
const parseAi = (resp) => {
  const raw = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
  if (!raw) throw new Error('AI provider returned no content');
  let s = String(raw).trim();
  const m = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) s = m[1].trim();
  try { return JSON.parse(s); } catch (e) { throw new Error('AI provider returned invalid JSON: ' + e.message); }
};
if (stopped()) return [{ json: { stopped: true } }];
const today = new Date().toISOString().slice(0, 10);
const system = 'You are the Eki social media strategist. Brand: Eki is a digital marketplace connecting African foodstuff vendors with buyers worldwide (garri, palm oil, spices, dried fish, and more). Tone: warm, community-driven, trustworthy, approachable. Generate unique content for each platform. Do not invent statistics, testimonials, prices, delivery promises or guarantees. Return ONLY valid JSON.';
const user = 'Generate social media content for ' + today + '. Return JSON with this exact structure:\n{\n  "tiktok": { "hook": "attention-grabbing first line", "video_script": "30-60 sec script with scenes", "caption": "short caption", "hashtags": "#tag1 #tag2 (5-8 tags)" },\n  "instagram": { "hook": "reel hook", "video_script": "reel script", "caption": "engaging caption with CTA", "hashtags": "#tag1 #tag2 (10-15 tags)" },\n  "facebook": { "hook": "scroll-stopping opener", "caption": "longer post with value and CTA", "hashtags": "#tag1 #tag2 (3-5 tags)", "video_script": "" }\n}\nRules: No offensive content. No false claims. No medical/legal/financial promises. No spammy hashtags. Each platform MUST have a unique caption. Focus on African foodstuff sourcing, cooking, community and trust.';
return [{ json: { stopped: false, ai_request: aiRequest(system, user, 0.85) } }];

