const content = parseAi($input.first().json);
const today = new Date().toISOString().slice(0, 10);
const offensiveRe = /\b(fuck|shit|damn|bitch|nigger|faggot|retard)\b/i;
const falseClaimRe = /\b(guaranteed|100%|proven to|always works|never fails|instant results)\b/i;
const medLegalFinRe = /\b(cure|diagnose|legal advice|financial advice|investment returns|medical treatment|prescription)\b/i;
const spamHashRe = /\b(follow4follow|f4f|like4like|l4l|followback|instalike|likeforlike)\b/i;
const platforms = ['tiktok', 'instagram', 'facebook'];
const rows = platforms.map((platform) => {
  const p = content[platform] || {};
  return { date: today, platform, content_type: platform === 'tiktok' ? 'short_video' : platform === 'instagram' ? 'reel' : 'post', hook: norm(p.hook), caption: norm(p.caption), hashtags: norm(p.hashtags), video_script: norm(p.video_script) };
});
const captions = rows.map((r) => r.caption.toLowerCase());
return rows.map((r) => {
  const issues = [];
  const text = r.caption + ' ' + r.video_script + ' ' + r.hook;
  if (!r.caption) issues.push('empty_caption');
  if (offensiveRe.test(text)) issues.push('offensive');
  if (falseClaimRe.test(text)) issues.push('false_claim');
  if (medLegalFinRe.test(text)) issues.push('med_legal_fin');
  if (spamHashRe.test(r.hashtags)) issues.push('spam_hashtags');
  if (captions.filter((c) => c === r.caption.toLowerCase()).length > 1) issues.push('duplicate');
  const passed = issues.length === 0;
  return { json: { ...r, status: passed ? 'approved' : 'flagged', autopilot_status: 'pending', scheduled_at: '', published_at: '', flag_reason: passed ? '' : issues.join(',') } };
});

